# frozen_string_literal: true

module SlimLint
  # Checks the Ruby generated by Slim's complete compilation pipeline.
  class Linter::Syntax < Linter
    include LinterRegistry

    on_start do |_sexp|
      validate_syntax
      :stop
    end

    private

    def validate_syntax
      ruby = ::Slim::Engine.new(file: document.file).call(document.source)
      diagnostic = syntax_diagnostic(ruby)
      report_diagnostic(diagnostic) if diagnostic
    rescue ::Temple::FilterError => e
      report_lint(document.sexp, "Unable to compile Slim: #{e.message}", severity: :error)
    end

    def syntax_diagnostic(ruby)
      parsed = ::RuboCop::ProcessedSource.new(ruby, RUBY_VERSION.to_f)
      parsed.diagnostics.find { |entry| %i[error fatal].include?(entry.level) }
    end

    def report_diagnostic(diagnostic)
      # Slim preserves source newlines, but may append code after the last one.
      line = diagnostic.location.line.clamp(1, [document.source_lines.length, 1].max)
      node = Struct.new(:line).new(line)
      report_lint(node, "Invalid Ruby generated by Slim: #{diagnostic.message}", severity: :error)
    end
  end
end
